 58| export class ReportService {
 59|   constructor(
 60|     private readonly sessions: SessionRepository,
 61|     private readonly bookings: BookingRepository,
 62|     private readonly now: () => number = Date.now,
 63|   ) {}
 64| 
 65|   /** `from` defaults to the Monday of the current week, `to` to six days after `from`. */
 66|   weekly(from?: string, to?: string): WeeklyReport {
 67|     let start: number;
 68|     if (from !== undefined) {
 69|       start = parseDay(from, "from");
 70|     } else {
 71|       const today = Date.parse(`${day(this.now())}T00:00:00Z`);
 72|       start = today - ((new Date(today).getUTCDay() + 6) % 7) * DAY_MS;
 73|     }
 74|     const end = to !== undefined ? parseDay(to, "to") : start + 6 * DAY_MS;
 75|     if (end < start) throw new DomainError("validation", "to must not be before from");
 76|     const fromDay = day(start);
 77|     const toDay = day(end);
 78| 
 79|     const sizes = new Set<string>();
 80|     const rows: SessionReportRow[] = [];
 81|     for (const s of this.sessions.list()) {
 82|       if (s.date < fromDay || s.date > toDay) continue;
 83|       const row: SessionReportRow = {
 84|         sessionId: s.id,
 85|         date: s.date,
 86|         start: s.start,
 87|         end: s.end,
 88|         status: s.status,
 89|         capacity: s.capacity,
 90|         ticketsSold: 0,
 91|         membersAdmitted: 0,
 92|         occupancy: 0,
 93|         hireIncomeCents: {},
 94|         refundedBookings: 0,
 95|         refundedCents: 0,
 96|         heldForIce: s.status === "held" || (s.iceHold === true && s.status !== "cancelled"),
 97|         cancelledForIce: s.status === "cancelled",
 98|       };
 99|       for (const b of this.bookings.listBySession(s.id)) {
100|         if (b.status === "refunded") {
101|           row.refundedBookings++;
102|           row.refundedCents += b.amountCents;
103|         } else if (b.status === "paid") {
104|           row.ticketsSold += b.tickets;
105|           if (b.membershipNumber !== undefined) row.membersAdmitted += b.tickets;
106|           for (const [size, qty] of Object.entries(b.hire)) {
107|             sizes.add(size);
108|             row.hireIncomeCents[size] = (row.hireIncomeCents[size] ?? 0) + qty * s.hirePriceCents;
109|           }
110|         }
111|       }
112|       row.occupancy = ratio(row.ticketsSold, s.capacity);
113|       rows.push(row);
114|     }
115| 
116|     const sorted = [...sizes].sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
117|     const totals: WeeklyReport["totals"] = {
118|       sessions: rows.length,
119|       ticketsSold: 0,
120|       membersAdmitted: 0,
121|       occupancy: 0,
122|       hireIncomeCents: {},
123|       refundedBookings: 0,
124|       refundedCents: 0,
125|       sessionsHeldForIce: 0,
126|       sessionsCancelledForIce: 0,
127|     };
128|     let capacity = 0;
129|     for (const r of rows) {
130|       capacity += r.capacity;
131|       totals.ticketsSold += r.ticketsSold;
132|       totals.membersAdmitted += r.membersAdmitted;
133|       totals.refundedBookings += r.refundedBookings;
134|       totals.refundedCents += r.refundedCents;
135|       if (r.heldForIce) totals.sessionsHeldForIce++;
136|       if (r.cancelledForIce) totals.sessionsCancelledForIce++;
137|       for (const [size, cents] of Object.entries(r.hireIncomeCents)) {
138|         totals.hireIncomeCents[size] = (totals.hireIncomeCents[size] ?? 0) + cents;
139|       }
140|     }
141|     totals.occupancy = ratio(totals.ticketsSold, capacity);
142|     return { from: fromDay, to: toDay, sizes: sorted, sessions: rows, totals };
143|   }
144| }
